import React, { useState, useEffect, useCallback } from "react";

export default function ManageApplications() {
  const API = process.env.REACT_APP_API_BASE_URL;

  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedApplication, setSelectedApplication] = useState(null);
  const [reviewComment, setReviewComment] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");

  // ---------------- FETCH APPLICATIONS ----------------
  const fetchApplicationsForReview = useCallback(async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API}/applications/applications`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json();

      if (response.ok) {
        setApplications(data.data || []);
      } else {
        setError(data.message || "Failed to fetch applications");
      }
    } catch (err) {
      setError("Network error. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [API]);

  useEffect(() => {
    fetchApplicationsForReview();
  }, [fetchApplicationsForReview]);

  // ---------------- UPDATE STATUS ----------------
  const updateApplicationStatus = async (
    applicationId,
    status
  ) => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API}/applications/verify/${applicationId}`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            status: status,
          }),
        }
      );

      const data = await response.json();

      if (response.ok) {
        setApplications((prev) =>
          prev.map((app) =>
            app.application_id === applicationId
              ? { ...app, status: status }
              : app
          )
        );
        setSelectedApplication(null);
        setReviewComment("");
        alert("Status updated successfully");
      } else {
        alert(data.message || "Failed to update application");
      }
    } catch (err) {
      alert("Network error. Please try again.");
    }
  };

  // ---------------- FILTER ----------------
  const getFilteredApplications = () => {
    if (filterStatus === "all") return applications;
    return applications.filter(
      (app) => app.status === filterStatus
    );
  };

  // ---------------- RENDER ----------------
  if (loading) {
    return (
      <div className="container mt-4" style={{ paddingTop: "80px" }}>
        <div className="text-center">
          <div className="spinner-border text-primary" />
          <p className="mt-2">
            Loading applications for review...
          </p>
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid mt-4"
      style={{ paddingTop: "120px" }}
    >
      <div className="card shadow">
        <div className="card-header bg-warning">
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h3 className="mb-0">
                Admin Review Panel
              </h3>
              <p className="mb-0">
                Applications: {applications.length}
              </p>
            </div>
            <select
              className="form-select"
              style={{ width: "200px" }}
              value={filterStatus}
              onChange={(e) =>
                setFilterStatus(e.target.value)
              }
            >
              <option value="all">
                All Applications
              </option>
              <option value="Pending">
                Pending
              </option>
              <option value="Approved by Authority">
                Approved by Authority
              </option>
              <option value="Rejected by Authority">
                Rejected by Authority
              </option>
              <option value="Approved by Admin">
                Approved by Admin
              </option>
              <option value="Rejected by Admin">
                Rejected by Admin
              </option>
            </select>
          </div>
        </div>

        <div className="card-body p-0">
          {error && (
            <div className="alert alert-danger m-3">
              {error}
            </div>
          )}

          {getFilteredApplications().length === 0 ? (
            <div className="text-center py-4">
              <h5>No Applications Found</h5>
            </div>
          ) : (
            <div
              className="table-responsive"
              style={{ maxHeight: "70vh" }}
            >
              <table className="table table-hover mb-0">
                <thead className="table-light">
                  <tr>
                    <th>ID</th>
                    <th>Student</th>
                    <th>Roll</th>
                    <th>Institute</th>
                    <th>CGPA</th>
                    <th>12th %</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>

                <tbody>
                  {getFilteredApplications().map(
                    (application) => (
                      <tr
                        key={application.application_id}
                      >
                        <td>
                          #
                          {application.application_id}
                        </td>
                        <td>
                          {application.student_name}
                        </td>
                        <td>{application.roll}</td>
                        <td>
                          {application.institute_name}
                        </td>
                        <td>
                          {application.cgpa}
                        </td>
                        <td>
                          {application.percent_12th}%
                        </td>
                        <td>
                          {getStatusBadge(
                            application.status
                          )}
                        </td>
                        <td>
                          {application.status ===
                            "Approved by Authority" && (
                            <>
                              <button
                                className="btn btn-success btn-sm me-1"
                                onClick={() =>
                                  updateApplicationStatus(
                                    application.application_id,
                                    "Approved by Admin"
                                  )
                                }
                              >
                                Approve
                              </button>
                              <button
                                className="btn btn-danger btn-sm"
                                onClick={() =>
                                  updateApplicationStatus(
                                    application.application_id,
                                    "Rejected by Admin"
                                  )
                                }
                              >
                                Reject
                              </button>
                            </>
                          )}
                        </td>
                      </tr>
                    )
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ---------------- STATUS BADGE ----------------
const getStatusBadge = (status) => {
  const colors = {
    Pending: "bg-warning",
    "Approved by Authority": "bg-info",
    "Rejected by Authority": "bg-danger",
    "Approved by Admin": "bg-success",
    "Rejected by Admin": "bg-dark",
  };

  return (
    <span
      className={`badge ${
        colors[status] || "bg-secondary"
      }`}
    >
      {status}
    </span>
  );
};
